"""Build ``generated/compose.dashboard.yaml`` text."""

from raft.core.core.config.settings.dashboard_config import (
    DASHBOARD_SERVICE_NAME,
    DashboardConfig,
)


class DashboardComposeYaml:
    """Compose fragment for the always-on dashboard service (or empty)."""

    def build(self, cfg: DashboardConfig) -> str:
        if not cfg.enabled:
            return self._empty()
        return "\n".join(self._service_lines(cfg)) + "\n"

    @staticmethod
    def _empty() -> str:
        return (
            "# Generated by `raft render` — always-on dashboard (disabled).\n"
            "services: {}\n"
        )

    def _service_lines(self, cfg: DashboardConfig) -> list[str]:
        port = cfg.port
        name = DASHBOARD_SERVICE_NAME
        return [
            "# Generated by `raft render` — always-on raft-dashboard.",
            "services:",
            f"  {name}:",
            *self._build_block(),
            *self._runtime_block(port),
            *self._volume_block(),
            *self._resources_block(),
        ]

    @staticmethod
    def _build_block() -> list[str]:
        return [
            "    build:",
            "      context: ./dashboard",
            "    working_dir: /raft",
            '    user: "${RAFT_HOST_UID:-0}:${RAFT_HOST_GID:-0}"',
            "    group_add:",
            '      - "${RAFT_DOCKER_GID:-0}"',
        ]

    @staticmethod
    def _runtime_block(port: int) -> list[str]:
        return [
            "    environment:",
            "      RAFT_DATA_HOME: /raft",
            f'      RAFT_SERVE_PORT: "{port}"',
            # Listen on all container interfaces; host mapping stays loopback.
            "      RAFT_SERVE_BIND: \"0.0.0.0\"",
            "    ports:",
            f'      - "127.0.0.1:{port}:{port}"',
        ]

    @staticmethod
    def _volume_block() -> list[str]:
        return [
            "    volumes:",
            "      - /var/run/docker.sock:/var/run/docker.sock",
            "      - .:/raft:ro",
            "      - ./settings.yaml:/raft/settings.yaml",
            "      - ./state/locks:/raft/state/locks",
            "      - ./state/firewall:/raft/state/firewall",
            "      - ./state/alerts:/raft/state/alerts",
            "      - ./state/serve:/raft/state/serve",
            "      - ./state/events:/raft/state/events",
            "      - ./state/metrics:/raft/state/metrics",
            "      - ./state/service-logs:/raft/state/service-logs",
            "      - ./state/scaling:/raft/state/scaling",
            "      - ./state/acme:/raft/state/acme",
            "      - ./certs:/raft/certs",
            "      - ./secrets:/raft/secrets",
            "      - ./generated:/raft/generated",
            "    restart: unless-stopped",
        ]

    @staticmethod
    def _resources_block() -> list[str]:
        return [
            "    deploy:",
            "      resources:",
            "        limits:",
            '          cpus: "0.50"',
            "          memory: 256M",
            "        reservations:",
            '          cpus: "0.05"',
            "          memory: 64M",
        ]
